import { startToolTimer } from "../tool-timer.ts";

function main(): void {
    const captured: string[] = [];
    const write = (text: string): void => {
        captured.push(text);
    };

    // Representative ExecuteCommand success invocation.
    const pending = renderToolPhase(
        "pending",
        { name: "ExecuteCommand", arguments: JSON.stringify({ command: "echo hello && sleep 0.2" }) },
        undefined,
        { color: true },
    );
    for (const line of pending) write(`PENDING: ${line}\n`);

    const timer = startToolTimer({
        write,
        isTTY: true,
        color: true,
        now: (() => {
            let t = 0;
            return () => {
                t += 123;
                return t;
            };
        })(),
    });
    timer.start();
    timer.stop();

    const success = renderToolPhase(
        "succeeded",
        { name: "ExecuteCommand", arguments: JSON.stringify({ command: "echo hello && sleep 0.2" }) },
        { exitCode: 0, stdout: "hello", stderr: "" },
        { color: true },
    );
    for (const line of success) write(`SUCCESS: ${line}\n`);

    const failure = renderToolPhase(
        "failed",
        { name: "ExecuteCommand", arguments: JSON.stringify({ command: "sh -c 'echo partial; echo boom >&2; exit 3'" }) },
        { exitCode: 3, stdout: "partial", stderr: "boom" },
        { color: true },
    );
    for (const line of failure) write(`FAILURE: ${line}\n`);

    const enroll = renderToolPhase(
        "succeeded",
        { name: "SpecKeeperEnroll", arguments: JSON.stringify({ token: "sk-live-secret-token" }) },
        { accessToken: "sk-live-result-secret", projectSlug: "demo-project" },
        { color: true },
    );
    for (const line of enroll) write(`ENROLL: ${line}\n`);

    process.stdout.write(captured.join(""));
}

main();
