async function llmRoutingDecision(
  command: string,
  runtime: MultiTurnLlmRuntime,
  promptPath: string,
  logger: NonNullable<GitCommandRouterOptions["logger"]>,
): Promise<GitCommandRouting> {
  let template: string;
