check("Edit inside start dir allowed", verdict("Edit", { path: `${START}/notes.md`, old_string: "a", new_string: "b" }, allow).decision === "safe");
check("Write outside both denied", verdict("Write", { path: "/etc/motd", content: "hi" }, allow).decision === "unsafe");
check("Edit outside both denied", verdict("Edit", { path: "/tmp/x", old_string: "a", new_string: "b" }, allow).decision === "unsafe");
check("traversal escape denied", verdict("Write", { path: `${SRC}/../outside.txt`, content: "hi" }, allow).decision === "unsafe");
check("touch inside start dir permitted", verdict("ExecuteCommand", { command: `touch ${START}/notes.md` }, allow).decision !== "unsafe");
check("touch outside both denied", verdict("ExecuteCommand", { command: "touch /tmp/x" }, allow).decision === "unsafe");
check("echo redirect outside denied", verdict("ExecuteCommand", { command: "echo hi > /tmp/x" }, allow).decision === "unsafe");

const disabled = { ...baseConfig, enabled: false };
check("disabled classifier allows Write", verdict("Write", { path: "/etc/motd", content: "hi" }, disabled).decision === "safe");

