check("Write outside both denied", verdict("Write", { path: "/etc/motd", content: "hi" }, allow).decision === "unsafe");
check("Edit outside both denied", verdict("Edit", { path: "/tmp/x", old_string: "a", new_string: "b" }, allow).decision === "unsafe");
