/**
 * Replace starting-directory placeholders in CLAUDE.md content with the
 * resolved pwd/canonical path values. Committed and runtime-generated files can
 * stay machine-independent while the prompt sent to the model still receives
 * the actual paths for the current run.
 */
export function substituteWorkspaceInitPlaceholders(
  content: string,
  init: Pick<WorkspaceInit, "pwd" | "canonicalPath">,
): string {
  return content
    .split(WORKSPACE_START_DIRECTORY_PLACEHOLDER)
    .join(init.canonicalPath)
    .split(INITIAL_WORKING_DIRECTORY_PLACEHOLDER)
    .join(init.pwd);
}"}]}

